#include <everett/profile.h>
using B=everett::storage_policy<everett::profile_unit::byte>;
using T=everett::storage_policy<everett::profile_unit::bit>;
using BC=everett::profile_cursor<B,everett::stream_role::native>;
using TC=everett::profile_cursor<T,everett::stream_role::native>;
void advance_byte(BC&c){c.advance();}
void advance_bit(TC&c){c.advance();}
auto compare_byte(BC&c){return c.advance_comparison();}
auto compare_bit(TC&c){return c.advance_comparison();}

